id			FinishCreateSelf();	virtual	void			HandleClick( const EventRecord &inMacEvent, SInt16 inPart );	virtual void			DrawSelf();	virtual void			MouseWithin( Point port, const EventRecord &inMacEvent);	Boolean					mFullScreen;	Boolean					mScreenBackuped;	Ptr						mOriginalScreen;	Ptr						mBkfullScreen;	Point					mWindowPoint;	CGameWindowAttachment	*mWinAttach;	// for DNML attributes	CSystem					*mSystem;	EventRecord				*mEvent;	Point					mWindowSize;	Point					mWindowOffset;	LMouseTracker			*mouseTracker;};#endif	// _H_CGameWindow